// Generate the brand CSS/JSON from web/src/theme.ts (the one place tokens are defined).
// Usage: npm run brand            (writes the files)
//        npm run brand -- --check (fails if any generated file is out of date)
import { readFileSync, writeFileSync, mkdirSync } from "node:fs";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";
import { brand, extra, series, benchmarkGrey, states, fonts } from "../src/theme.ts";

const here = dirname(fileURLToPath(import.meta.url));
const root = resolve(here, "..", "..");
const vars = { ...brand, ...extra };
const header = "/* GENERATED by web/scripts/gen-brand.mjs from web/src/theme.ts - do not edit. */\n";
const rootBlock = ":root{\n" + Object.entries(vars).map(([k, v]) => `  --${k}:${v};`).join("\n") + "\n}\n\n";
const css = header + rootBlock + readFileSync(resolve(here, "brand-base.css"), "utf8");
const json = JSON.stringify({ brand, extra, series, benchmarkGrey, states, fonts }, null, 2) + "\n";

const outputs = {
  [resolve(root, "web/src/brand.css")]: css,
  [resolve(root, "autobot/assets/brand.css")]: css,
  [resolve(root, "autobot/assets/brand.json")]: json,
};
const check = process.argv.includes("--check");
let stale = [];
for (const [path, text] of Object.entries(outputs)) {
  let cur = null;
  try { cur = readFileSync(path, "utf8"); } catch { /* missing */ }
  if (cur === text) continue;
  if (check) stale.push(path);
  else { mkdirSync(dirname(path), { recursive: true }); writeFileSync(path, text); console.log("wrote", path); }
}
if (check && stale.length) { console.error("out of date:\n  " + stale.join("\n  ") + "\nrun: npm run brand"); process.exit(1); }
if (check) console.log("brand files up to date");
